export default {
  plugins: {
    "@tailwindcss/postcss": {}
  }
};

// Google Gemini embeddings — embedContent / batchEmbedContents
const BASE = "https://generativelanguage.googleapis.com/v1beta";

function modelPath(model) {
  return model.startsWith("models/") ? model : `models/${model}`;
}

export default {
  buildUrl: (model, creds, { input } = {}) => {
    const apiKey = creds.apiKey || creds.accessToken;
    const path = modelPath(model);
    const op = Array.isArray(input) ? "batchEmbedContents" : "embedContent";
    return `${BASE}/${path}:${op}?key=${encodeURIComponent(apiKey)}`;
  },
  buildHeaders: () => ({ "Content-Type": "application/json" }),
  buildBody: (model, { input, dimensions }) => {
    const m = modelPath(model);
    const outputDimensionality = Number(dimensions);
    const hasOutputDimensionality = Number.isFinite(outputDimensionality) && outputDimensionality > 0;
    if (Array.isArray(input)) {
      return {
        requests: input.map((text) => ({
          model: m,
          content: { parts: [{ text: String(text) }] },
          ...(hasOutputDimensionality ? { outputDimensionality } : {}),
        })),
      };
    }
    return {
      model: m,
      content: { parts: [{ text: String(input) }] },
      ...(hasOutputDimensionality ? { outputDimensionality } : {}),
    };
  },
  normalize: (responseBody, model) => {
    if (responseBody.object === "list" && Array.isArray(responseBody.data)) return responseBody;
    let items = [];
    if (Array.isArray(responseBody.embeddings)) {
      items = responseBody.embeddings.map((emb, idx) => ({
        object: "embedding",
        index: idx,
        embedding: emb.values || [],
      }));
    } else if (responseBody.embedding?.values) {
      items = [{ object: "embedding", index: 0, embedding: responseBody.embedding.values }];
    }
    return {
      object: "list",
      data: items,
      model,
      usage: { prompt_tokens: 0, total_tokens: 0 },
    };
  },
};

// GitHub Copilot embeddings — api.githubcopilot.com/embeddings with the short-lived Copilot token.
// The GitHub Models inference API (models.github.ai) was retired on 2026-07-30.
import createOpenAIEmbeddingAdapter from "./openai.js";
import { GITHUB_COPILOT } from "../../config/appConstants.js";

const baseAdapter = createOpenAIEmbeddingAdapter("github");

export default {
  ...baseAdapter,
  buildHeaders: (creds) => ({
    "Content-Type": "application/json",
    "Authorization": `Bearer ${creds.copilotToken || creds.providerSpecificData?.copilotToken || creds.accessToken}`,
    "copilot-integration-id": "vscode-chat",
    "editor-version": `vscode/${GITHUB_COPILOT.VSCODE_VERSION}`,
    "editor-plugin-version": `copilot-chat/${GITHUB_COPILOT.COPILOT_CHAT_VERSION}`,
    "user-agent": GITHUB_COPILOT.USER_AGENT,
    "x-github-api-version": GITHUB_COPILOT.API_VERSION,
  }),
};

import { resolveOllamaLocalHost } from "../../config/providers.js";

export default {
  buildUrl: (_model, creds) => {
    const rawHost = resolveOllamaLocalHost(creds);
    const host = String(rawHost || "")
      .replace(/\/+$/, "")
      .replace(/\/v1\/embeddings$/, "")
      .replace(/\/v1$/, "");
    return `${host}/v1/embeddings`;
  },
  buildHeaders: (creds) => {
    const headers = {
      "Content-Type": "application/json",
    };
    if (creds?.apiKey) {
      headers["Authorization"] = `Bearer ${creds.apiKey}`;
    }
    return headers;
  },
  buildBody: (model, { input, encoding_format, dimensions }) => {
    const body = { model, input };
    if (encoding_format) body.encoding_format = encoding_format;
    if (dimensions != null && dimensions !== "") {
      const dim = Number(dimensions);
      if (Number.isFinite(dim) && dim > 0) body.dimensions = dim;
    }
    return body;
  },
  normalize: (responseBody) => responseBody,
};

// Custom node providers (openai-compatible-* / custom-embedding-*) — baseUrl from credentials
import createOpenAIEmbeddingAdapter from "./openai.js";

const baseAdapter = createOpenAIEmbeddingAdapter("openai");

export default {
  ...baseAdapter,
  buildUrl: (_model, creds) => {
    const rawBaseUrl = creds?.providerSpecificData?.baseUrl || "https://api.openai.com/v1";
    const baseUrl = rawBaseUrl.replace(/\/$/, "").replace(/\/embeddings$/, "");
    return `${baseUrl}/embeddings`;
  },
};

// Self-hosted embeddings — like openaiCompatNode, but the baseUrl is REQUIRED.
//
// openaiCompatNode falls back to https://api.openai.com/v1 when a connection
// carries no providerSpecificData.baseUrl. For a custom NODE that default is
// defensible: the node was created by pointing at some OpenAI-compatible URL, and
// OpenAI is the archetype. For a provider whose entire purpose is "my own
// server", it is actively harmful — a connection saved without a baseUrl sends
// the INPUT TEXT and the API KEY to OpenAI, silently, under a provider named
// "Self-hosted Embedding".
//
// Observed exactly that with a placeholder connection (2026-08-04):
//
//   [selfhosted-embedding/embedding] [401]: Incorrect API key provided: abc.
//   You can find your API key at https://platform.openai.com/account/api-keys.
//
// The key "abc" was typed as a throwaway for a LOCAL server and left the network.
// A self-hosted provider must never have a cloud fallback, so this one refuses
// instead: no baseUrl means a configuration error, reported as such.
import createOpenAIEmbeddingAdapter from "./openai.js";

const baseAdapter = createOpenAIEmbeddingAdapter("openai");

export class MissingBaseUrlError extends Error {
  constructor() {
    super(
      "Self-hosted Embedding needs an endpoint: set this connection's baseUrl to " +
        "the OpenAI base URL of your server, e.g. http://host:8080/v1 (note the /v1 — " +
        "\"/embeddings\" is appended to it). Refusing to fall back to api.openai.com, " +
        "which would send your input and API key to OpenAI."
    );
    this.name = "MissingBaseUrlError";
    this.isConfigError = true;
  }
}

export default {
  ...baseAdapter,
  buildUrl: (_model, creds) => {
    const rawBaseUrl = creds?.providerSpecificData?.baseUrl;
    if (!rawBaseUrl || !String(rawBaseUrl).trim()) throw new MissingBaseUrlError();
    // Accept either the OpenAI base or a full embeddings URL, so a value pasted
    // from a curl example works as well as one typed from the help text.
    const baseUrl = String(rawBaseUrl).trim().replace(/\/$/, "").replace(/\/embeddings$/, "");
    return `${baseUrl}/embeddings`;
  },
};

// Antigravity image adapter - delegates to the executor for correct request
// envelope (project, model, requestType, sessionId) and auth headers.
import { nowSec, sizeToAspectRatio } from "./_base.js";
import { getExecutor } from "../../executors/index.js";

// Antigravity accepts up to 10 reference images per request
const MAX_REFERENCE_IMAGES = 10;

// Convert image input (data URI or raw base64) to Gemini inlineData part
function resolveImageInput(input) {
  if (input && typeof input === "object") {
    input = input.image_url?.url || input.url || input.data || input.b64_json;
  }
  if (!input || typeof input !== "string") return null;
  // data:image/png;base64,... format
  const dataUriMatch = input.match(/^data:(image\/[^;]+);base64,(.+)$/);
  if (dataUriMatch) {
    return { inlineData: { mimeType: dataUriMatch[1], data: dataUriMatch[2] } };
  }
  // Raw base64 string (assume PNG)
  if (/^[A-Za-z0-9+/]/.test(input) && input.length > 100 && !input.startsWith("http")) {
    return { inlineData: { mimeType: "image/png", data: input } };
  }
  return null;
}

// Collect reference images from the accepted request field shapes
function collectImageInputs(body) {
  const candidates = [
    body.reference_images,
    body.images,
    body.reference_image,
    body.image,
  ];
  return candidates
    .flatMap(v => (Array.isArray(v) ? v : v ? [v] : []))
    .slice(0, MAX_REFERENCE_IMAGES);
}

export default {
  // Delegate to executor instead of building URL/headers/body manually
  useExecutor: true,

  // Stubs - required by imageGenerationCore interface but unused with useExecutor
  buildUrl: () => "",
  buildHeaders: () => ({}),
  buildBody: () => ({}),

  async executeViaExecutor(model, body, credentials, log) {
    const executor = getExecutor("antigravity");
    if (!executor) throw new Error("Antigravity executor not found");

    // Ensure we use an image model for image generation
    const isImageModel = (m) => /image|imagen|image-generation/i.test(m || "");
    let targetModel = isImageModel(model) ? model : "gemini-3.1-flash-image";

    // Aspect ratio: explicit body.aspect_ratio wins, then body.size
    let ratio = null;
    if (body.aspect_ratio && /^\d{1,2}:\d{1,2}$/.test(String(body.aspect_ratio))) {
      ratio = String(body.aspect_ratio);
    } else if (body.size && typeof body.size === "string") {
      ratio = sizeToAspectRatio(body.size);
    }
    if (ratio) {
      const suffix = ratio.replace(":", "x");
      if (!targetModel.includes(suffix)) {
        targetModel = `${targetModel}-${suffix}`;
      }
    }

    // Gemini image models have no negative prompt param — fold it into the prompt text
    const prompt = body.negative_prompt
      ? `${body.prompt}\n\nNegative prompt: ${body.negative_prompt}`
      : body.prompt;

    // Build parts: reference images first, then the text prompt
    const parts = [];
    for (const imageInput of collectImageInputs(body)) {
      const inlineData = resolveImageInput(imageInput);
      if (inlineData) parts.push(inlineData);
    }
    parts.push({ text: prompt });

    const chatBody = {
      contents: [{ role: "user", parts }],
    };

    const result = await executor.execute({
      model: targetModel,
      body: chatBody,
      stream: false,
      credentials,
      log,
    });

    if (!result.response.ok) {
      const text = await result.response.text();
      const err = new Error(text || `HTTP ${result.response.status}`);
      err.status = result.response.status;
      try {
        const json = JSON.parse(text);
        const details = json.error?.details || [];
        for (const d of details) {
          const resetTimeStr = d.metadata?.quotaResetTimeStamp;
          if (resetTimeStr) {
            const ms = new Date(resetTimeStr).getTime();
            if (ms > Date.now()) {
              err.resetsAtMs = ms;
              break;
            }
          }
        }
      } catch {}
      throw err;
    }

    return result.response.json();
  },

  normalize: (responseBody, prompt) => {
    const candidates = responseBody.candidates || responseBody.response?.candidates || [];
    const parts = candidates[0]?.content?.parts || [];
    const images = parts.filter((p) => p.inlineData?.data).map((p) => ({
      b64_json: p.inlineData.data,
    }));
    return {
      created: nowSec(),
      data: images.length > 0 ? images : [{ b64_json: "", revised_prompt: prompt }],
    };
  },
};

// Black Forest Labs (FLUX) — async submit + polling_url
import { sleep, nowSec, POLL_INTERVAL_MS, POLL_TIMEOUT_MS } from "./_base.js";
import { PROVIDER_MEDIA } from "../../providers/index.js";

const BASE_URL = PROVIDER_MEDIA["black-forest-labs"]?.imageConfig?.baseUrl;

export default {
  async: true,
  buildUrl: (model) => `${BASE_URL}/${model}`,
  buildHeaders: (creds) => {
    const key = creds?.apiKey || creds?.accessToken;
    return { "Content-Type": "application/json", "x-key": key };
  },
  buildBody: (_model, body) => {
    const req = { prompt: body.prompt };
    if (body.size) {
      const [w, h] = body.size.split("x").map(Number);
      if (w) req.width = w;
      if (h) req.height = h;
    }
    if (body.image) req.image_prompt = body.image;
    return req;
  },
  async parseResponse(response, { headers }) {
    const data = await response.json();
    const pollingUrl = data.polling_url;
    if (!pollingUrl) throw new Error("BFL: no polling_url returned");
    const deadline = Date.now() + POLL_TIMEOUT_MS;
    while (Date.now() < deadline) {
      await sleep(POLL_INTERVAL_MS);
      const r = await fetch(pollingUrl, { headers: { "x-key": headers["x-key"], "Accept": "application/json" } });
      if (!r.ok) throw new Error(`BFL status ${r.status}`);
      const s = await r.json();
      if (s.status === "Ready") return s;
      if (s.status === "Error" || s.status === "Failed") throw new Error(s.error || "BFL generation failed");
    }
    throw new Error("BFL polling timeout");
  },
  normalize: (responseBody) => {
    const sample = responseBody.result?.sample;
    if (sample) return { created: nowSec(), data: [{ url: sample }] };
    return { created: nowSec(), data: [] };
  },
};

// ChatGPT Web image adapter — delegates to the executor's picture_v2 in-page
// generation flow (prepare → conversation SSE → poll → download).
import { nowSec } from "./_base.js";
import { getExecutor } from "../../executors/index.js";

export default {
  useExecutor: true,

  // Stubs - required by imageGenerationCore interface but unused with useExecutor
  buildUrl: () => "",
  buildHeaders: () => ({}),
  buildBody: () => ({}),

  async executeViaExecutor(model, body, credentials, log) {
    const executor = getExecutor("chatgpt-web");
    if (!executor) throw new Error("ChatGPT Web executor not found");

    const media = await executor.generateMedia({
      prompt: body.prompt,
      n: Math.max(1, Math.min(4, Number(body.n) || 1)),
      size: body.size,
      credentials,
      log,
    });

    return {
      created: nowSec(),
      data: media.map((m) => ({
        b64_json: m.b64,
        ...(m.mime ? { mime_type: m.mime } : {}),
      })),
    };
  },

  normalize: (responseBody) => responseBody,
};

import { nowSec, urlToBase64 } from "./_base.js";
import { PROVIDER_MEDIA } from "../../providers/index.js";

const BASE_URL = PROVIDER_MEDIA["cloudflare-ai"]?.imageConfig?.baseUrl;

const MULTIPART_MODELS = new Set([
  "@cf/black-forest-labs/flux-2-dev",
  "@cf/black-forest-labs/flux-2-klein-4b",
  "@cf/black-forest-labs/flux-2-klein-9b",
]);

const OPTIONAL_FIELDS = [
  "negative_prompt",
  "guidance",
  "seed",
  "num_steps",
  "steps",
  "strength",
];

function sizeToDimensions(size) {
  const match = /^(\d+)x(\d+)$/.exec(String(size || ""));
  if (!match) return {};
  return {
    width: Number(match[1]),
    height: Number(match[2]),
  };
}

function getDimensions(body) {
  return {
    ...sizeToDimensions(body.size),
    ...(Number.isFinite(Number(body.width)) ? { width: Number(body.width) } : {}),
    ...(Number.isFinite(Number(body.height)) ? { height: Number(body.height) } : {}),
  };
}

async function resolveImageInput(value) {
  if (Array.isArray(value)) {
    return { bytes: value, b64: Buffer.from(value).toString("base64") };
  }
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  if (!trimmed) return null;
  if (/^https?:\/\//i.test(trimmed)) {
    const b64 = await urlToBase64(trimmed);
    return { bytes: base64ToBytes(b64), b64 };
  }
  const match = /^data:image\/[^;]+;base64,(.+)$/i.exec(trimmed);
  const b64 = match ? match[1] : trimmed;
  return { bytes: base64ToBytes(b64), b64 };
}

function base64ToBytes(value) {
  try {
    return Array.from(Buffer.from(value, "base64"));
  } catch {
    return value;
  }
}

function addOptionalFields(target, body, append) {
  for (const key of OPTIONAL_FIELDS) {
    const value = body[key];
    if (value === undefined || value === null || value === "") continue;
    append(target, key, value);
  }
}

async function buildJsonBody(body) {
  const req = { prompt: body.prompt, ...getDimensions(body) };

  addOptionalFields(req, body, (target, key, value) => {
    target[key] = value;
  });

  const imageData = await resolveImageInput(body.image);
  if (imageData) {
    req.image_b64 = imageData.b64;
    req.image = imageData.bytes;
  }

  const maskData = await resolveImageInput(body.mask_image || body.maskImage || body.mask);
  if (maskData) {
    req.mask_b64 = maskData.b64;
    req.mask = maskData.bytes;
    req.mask_image = maskData.bytes;
  }

  return req;
}

function buildMultipartBody(body) {
  const form = new FormData();
  form.append("prompt", body.prompt);

  const dimensions = getDimensions(body);
  for (const [key, value] of Object.entries(dimensions)) {
    form.append(key, String(value));
  }

  addOptionalFields(form, body, (target, key, value) => {
    target.append(key, String(value));
  });

  return form;
}

function imageItemFromString(value) {
  if (typeof value !== "string" || !value) return null;
  if (/^data:image\/[^;]+;base64,/i.test(value)) {
    return { b64_json: value.replace(/^data:image\/[^;]+;base64,/i, "") };
  }
  if (/^https?:\/\//i.test(value)) return { url: value };
  return { b64_json: value };
}

function normalizeCloudflareResponse(responseBody) {
  if (responseBody?.created && Array.isArray(responseBody?.data)) return responseBody;

  const result = responseBody?.result ?? responseBody;
  const queuedResponse = Array.isArray(result?.responses)
    ? result.responses.find((item) => item?.success !== false)?.result
    : null;
  if (queuedResponse) return normalizeCloudflareResponse(queuedResponse);

  const image =
    (typeof result === "string" ? result : null) ||
    result?.image ||
    result?.data?.[0]?.b64_json ||
    result?.data?.[0]?.url;

  const item = imageItemFromString(image);
  return {
    created: nowSec(),
    data: item ? [item] : [],
  };
}

export default {
  buildUrl: (model, creds) => {
    const accountId = creds?.providerSpecificData?.accountId;
    if (!accountId) throw new Error("cloudflare-ai requires accountId in providerSpecificData");
    return `${BASE_URL}/${accountId}/ai/run/${model}`;
  },

  buildHeaders: (creds, requestBody) => {
    const headers = {};
    const isMultipart = typeof FormData !== "undefined" && requestBody instanceof FormData;
    if (!isMultipart) {
      headers["Content-Type"] = "application/json";
    }
    const key = creds?.apiKey || creds?.accessToken;
    if (key) headers.Authorization = `Bearer ${key}`;
    return headers;
  },

  buildBody: async (model, body) => (
    MULTIPART_MODELS.has(model)
      ? buildMultipartBody(body)
      : await buildJsonBody(body)
  ),

  async parseResponse(response) {
    const contentType = (response.headers.get("Content-Type") || "").toLowerCase();
    if (contentType.startsWith("image/")) {
      const buf = await response.arrayBuffer();
      return {
        created: nowSec(),
        data: [{ b64_json: Buffer.from(buf).toString("base64") }],
      };
    }

    const json = await response.json();
    return normalizeCloudflareResponse(json);
  },

  normalize: normalizeCloudflareResponse,
};

// Codex OAuth image generation: native Images API for GPT Image, Responses SSE for edits.
import { randomUUID } from "node:crypto";
import { nowSec } from "./_base.js";
import { PROVIDERS } from "../../config/providers.js";
import { PROVIDER_MEDIA } from "../../providers/index.js";
import { CODEX_CLI_VERSION } from "../../config/appConstants.js";

const CODEX_RESPONSES_URL = PROVIDERS["codex"].baseUrl;
// Codex OAuth image generation uses the native Images endpoint. The Responses
// image_generation path has returned unsupported `complexity=medium` errors for
// GPT Image models. Native has ignored explicit n/size/format controls,
// so preserve Responses for those requests, edits, and older virtual models.
const CODEX_IMAGES_GENERATIONS_URL = PROVIDER_MEDIA.codex.imageConfig.baseUrl;
const CODEX_USER_AGENT = `codex_cli_rs/${CODEX_CLI_VERSION}`;
const CODEX_ORIGINATOR = "codex_cli_rs";
const CODEX_MODEL_SUFFIX = "-image";
const CODEX_REF_DETAIL = "high";
// Only drives the image_generation tool call; any chat model on the plan works as host.
const CODEX_IMAGES_MAIN_MODEL = "gpt-6-sol";
const CODEX_TOOL_IMAGE_MODELS = new Set([
  "gpt-image-1.5",
  "gpt-image-2",
  "gpt-image-2.5",
  "gpt-image-2.5-flare",
  "gpt-image-2.5-sunburst",
  "gpt-image-2.6-flare",
  "gpt-image-2.6-sunburst",
]);

function decodeOpenAIAuthClaims(token) {
  try {
    const parts = String(token || "").split(".");
    if (parts.length !== 3) return null;
    const b64 = parts[1].replace(/-/g, "+").replace(/_/g, "/");
    const pad = (4 - (b64.length % 4)) % 4;
    const payload = JSON.parse(Buffer.from(b64 + "=".repeat(pad), "base64").toString("utf8"));
    return payload?.["https://api.openai.com/auth"] || null;
  } catch {
    return null;
  }
}

function decodeAccountId(idToken) {
  return decodeOpenAIAuthClaims(idToken)?.chatgpt_account_id || null;
}

// Token claims first: the stored chatgptPlanType is only set at OAuth/import time and goes stale on plan changes.
function resolveChatgptPlanType(creds) {
  return decodeOpenAIAuthClaims(creds?.accessToken)?.chatgpt_plan_type
    || decodeOpenAIAuthClaims(creds?.idToken)?.chatgpt_plan_type
    || creds?.providerSpecificData?.chatgptPlanType
    || null;
}

function stripImageSuffix(model) {
  return model.endsWith(CODEX_MODEL_SUFFIX) ? model.slice(0, -CODEX_MODEL_SUFFIX.length) : model;
}

function resolveCodexImageModels(model) {
  if (CODEX_TOOL_IMAGE_MODELS.has(model)) {
    return { responsesModel: CODEX_IMAGES_MAIN_MODEL, toolModel: model };
  }
  return { responsesModel: stripImageSuffix(model), toolModel: null };
}

function hasImageRefs(body) {
  return Boolean(body?.image || (Array.isArray(body?.images) && body.images.length > 0));
}

function shouldUseNativeGeneration(model, body = {}) {
  // Native Codex has been observed returning one auto-sized PNG even when n,
  // size, or output_format requests something else. Do not silently reroute
  // those requests to a transport that cannot honor their output controls.
  return CODEX_TOOL_IMAGE_MODELS.has(model)
    && !hasImageRefs(body)
    && (body.n == null || body.n === 1)
    && (!body.size || body.size === "auto")
    && (!body.output_format || body.output_format.toLowerCase() === "png")
    && (!body.background || ["auto", "opaque"].includes(body.background))
    && (!body.quality || ["auto", "low", "medium", "high"].includes(body.quality))
    && body.output_compression == null;
}

function buildNativeGenerationBody(model, body) {
  return {
    model,
    prompt: body.prompt,
    n: 1,
    size: "auto",
    quality: body.quality || "auto",
    background: body.background || "auto",
    output_format: "png",
  };
}

function toDataUrl(input) {
  if (!input || typeof input !== "string") return null;
  if (/^data:image\//i.test(input) || /^https?:\/\//i.test(input)) return input;
  return `data:image/png;base64,${input}`;
}

function buildContent(prompt, refs, detail = CODEX_REF_DETAIL) {
  const content = [];
  refs.forEach((url, index) => {
    content.push({ type: "input_text", text: `<image name=image${index + 1}>` });
    content.push({ type: "input_image", image_url: url, detail });
    content.push({ type: "input_text", text: "</image>" });
  });
  content.push({ type: "input_text", text: prompt });
  return content;
}

function extractStreamError(data) {
  if (!data) return null;
  if (typeof data === "string") return data;
  if (data.error?.message) return data.error.message;
  if (data.response?.error?.message) return data.response.error.message;
  if (data.item?.error?.message) return data.item.error.message;
  if (data.response?.status_details?.error?.message) return data.response.status_details.error.message;
  if (typeof data.error === "string") return data.error;
  if (typeof data.message === "string") return data.message;
  return null;
}

function normalizeResponsesUsage(raw) {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const input = raw.input_tokens ?? raw.prompt_tokens;
  const output = raw.output_tokens ?? raw.completion_tokens;
  if (!Number.isSafeInteger(input) || input < 0 || !Number.isSafeInteger(output) || output < 0) return null;

  const usage = {
    prompt_tokens: input,
    completion_tokens: output,
    total_tokens: Number.isSafeInteger(raw.total_tokens) ? raw.total_tokens : input + output,
  };
  const inputDetails = raw.input_tokens_details ?? raw.prompt_tokens_details;
  const cacheWriteDetails = inputDetails?.cache_write_tokens_details;
  const cached = inputDetails?.cached_tokens;
  const reasoning = raw.output_tokens_details?.reasoning_tokens ?? raw.completion_tokens_details?.reasoning_tokens;
  if (Number.isSafeInteger(cached) && cached >= 0) usage.cached_tokens = cached;
  if (Number.isSafeInteger(inputDetails?.cache_write_tokens) && inputDetails.cache_write_tokens >= 0) {
    usage.cache_write_tokens = inputDetails.cache_write_tokens;
  }
  if (Number.isSafeInteger(cacheWriteDetails?.ttl_30m_tokens) && cacheWriteDetails.ttl_30m_tokens >= 0) {
    usage.cache_write_30m_tokens = cacheWriteDetails.ttl_30m_tokens;
  }
  if (Number.isSafeInteger(cacheWriteDetails?.ttl_12h_tokens) && cacheWriteDetails.ttl_12h_tokens >= 0) {
    usage.cache_write_12h_tokens = cacheWriteDetails.ttl_12h_tokens;
  }
  if (Number.isSafeInteger(reasoning) && reasoning >= 0) usage.reasoning_tokens = reasoning;
  return usage;
}

function nativeImageSseResponse(result) {
  return new Response(`event: done\ndata: ${JSON.stringify(result)}\n\n`, {
    headers: {
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache, no-transform",
      "Access-Control-Allow-Origin": "*",
    },
  });
}

// Parse Codex SSE stream → final base64 image. Optional callbacks for client streaming.
async function parseStream(response, log, callbacks = {}) {
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let imageB64 = null;
  let upstreamError = null;
  let assistantText = "";
  let lastEvent = null;
  let bytesReceived = 0;
  let lastProgressLogMs = 0;
  let usage = null;

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      bytesReceived += value?.byteLength || 0;
      buffer += decoder.decode(value, { stream: true });

      let sepIdx;
      while ((sepIdx = buffer.indexOf("\n\n")) !== -1) {
        const block = buffer.slice(0, sepIdx);
        buffer = buffer.slice(sepIdx + 2);

        const lines = block.split("\n");
        let eventName = null;
        let dataStr = "";
        for (const line of lines) {
          if (line.startsWith("event:")) eventName = line.slice(6).trim();
          else if (line.startsWith("data:")) dataStr += line.slice(5).trim();
        }
        if (!eventName) continue;
        if (eventName !== lastEvent) {
          log?.info?.("IMAGE", `codex progress: ${eventName}`);
          lastEvent = eventName;
        }

        const now = Date.now();
        if (callbacks.onProgress && now - lastProgressLogMs > 200) {
          lastProgressLogMs = now;
          callbacks.onProgress({ stage: eventName, bytesReceived });
        }

        if ((eventName === "error" || eventName === "response.failed") && dataStr) {
          let data;
          try { data = JSON.parse(dataStr); } catch {}
          const error = data?.error || data?.response?.error || data;
          const err = new Error(error?.message || `Codex upstream failed (${eventName})`);
          for (const key of ["code", "type", "param"]) {
            if (typeof error?.[key] === "string") err[key] = error[key];
          }
          throw err;
        }

        if (eventName === "response.image_generation_call.partial_image" && dataStr) {
          try {
            const data = JSON.parse(dataStr);
            if (callbacks.onPartialImage && data?.partial_image_b64) {
              callbacks.onPartialImage({ b64_json: data.partial_image_b64, index: data.partial_image_index });
            }
          } catch {}
        }

        if (eventName === "response.output_text.delta" && dataStr) {
          try {
            assistantText += JSON.parse(dataStr)?.delta || "";
          } catch {}
        }

        if (eventName === "response.output_item.done" && dataStr) {
          try {
            const data = JSON.parse(dataStr);
            const item = data?.item;
            if (item?.type === "image_generation_call") {
              if (item.result) imageB64 = item.result;
              else upstreamError = extractStreamError(item) || upstreamError;
            } else if (item?.type === "message") {
              assistantText = item.content
                ?.map((part) => (typeof part === "string" ? part : part?.text || part?.output_text))
                .filter(Boolean)
                .join(" ") || assistantText;
            }
          } catch {}
        }

        if ((eventName === "response.completed" || eventName === "response.done") && dataStr) {
          try {
            const data = JSON.parse(dataStr);
            usage = normalizeResponsesUsage(data?.response?.usage ?? data?.usage) || usage;
            for (const item of data?.response?.output || data?.output || []) {
              if (item?.type === "image_generation_call" && item.result) imageB64 = item.result;
            }
          } catch {}
        }
      }
    }
  } catch (error) {
    try { await reader.cancel(); } catch {}
    throw error;
  } finally {
    reader.releaseLock();
  }
  if (!imageB64 && !upstreamError && assistantText) {
    upstreamError = `Codex returned text instead of an image: "${assistantText.trim().slice(0, 300)}"`;
  }
  return { imageB64, usage, error: upstreamError };
}

// SSE Response that pipes codex progress + partial + done events to client
function buildSseResponse(providerResponse, log, onSuccess, onUsage) {
  const stream = new ReadableStream({
    async start(controller) {
      const enc = new TextEncoder();
      const send = (event, data) => {
        controller.enqueue(enc.encode(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`));
      };
      try {
        const { imageB64: b64, usage, error: upstreamError } = await parseStream(providerResponse, log, {
          onProgress: (info) => send("progress", info),
          onPartialImage: (info) => send("partial_image", info),
        });
        if (!b64) {
          send("error", { message: upstreamError || "Codex completed without an image. No upstream image result was provided." });
        } else {
          if (usage && onUsage) await onUsage(usage);
          if (onSuccess) await onSuccess();
          send("done", { created: nowSec(), data: [{ b64_json: b64 }] });
        }
      } catch (err) {
        send("error", {
          message: err?.message || "Stream failed",
          ...(err?.code ? { code: err.code } : {}),
          ...(err?.type ? { type: err.type } : {}),
          ...(err?.param ? { param: err.param } : {}),
        });
      } finally {
        controller.close();
      }
    },
  });
  return new Response(stream, {
    headers: {
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache, no-transform",
      "Connection": "keep-alive",
      "X-Accel-Buffering": "no",
      "Access-Control-Allow-Origin": "*",
    },
  });
}

export default {
  stream: true,
  // ChatGPT Free accounts have the image_generation tool stripped server-side
  // (upstream returns 400 "Tool choice 'image_generation' must be specified with 'tools' parameter").
  // Unknown plan is allowed so accounts without plan claims keep working.
  canUseCredentials: (creds) => resolveChatgptPlanType(creds) !== "free",
  buildUrl: (model, creds, body) => shouldUseNativeGeneration(model, body)
    ? CODEX_IMAGES_GENERATIONS_URL
    : CODEX_RESPONSES_URL,
  buildHeaders: (creds, requestBody) => {
    const accountId = creds?.providerSpecificData?.chatgptAccountId || decodeAccountId(creds?.idToken);
    return {
      "accept": requestBody?.prompt && !requestBody?.input
        ? "application/json"
        : "text/event-stream, application/json",
      "authorization": `Bearer ${creds?.accessToken || ""}`,
      "chatgpt-account-id": accountId || "",
      "content-type": "application/json",
      "originator": CODEX_ORIGINATOR,
      "session_id": randomUUID(),
      "user-agent": CODEX_USER_AGENT,
      "version": CODEX_CLI_VERSION,
      "x-client-request-id": randomUUID(),
    };
  },
  buildBody: (model, body) => {
    if (shouldUseNativeGeneration(model, body)) return buildNativeGenerationBody(model, body);

    const refs = [];
    if (Array.isArray(body.images)) body.images.forEach((i) => { const u = toDataUrl(i); if (u) refs.push(u); });
    const single = toDataUrl(body.image);
    if (single) refs.push(single);
    const detail = body.image_detail || CODEX_REF_DETAIL;
    const { responsesModel, toolModel } = resolveCodexImageModels(model);
    const imgTool = { type: "image_generation", output_format: (body.output_format || "png").toLowerCase() };
    if (toolModel) {
      imgTool.action = refs.length > 0 ? "edit" : "generate";
      imgTool.model = toolModel;
    }
    if (body.size && body.size !== "") imgTool.size = body.size;
    if (body.quality && body.quality !== "") imgTool.quality = body.quality;
    // The ChatGPT Codex backend currently rejects every explicit complexity level.
    // Omit it so GPT Image 2.6 uses its supported upstream default.
    if (body.background && body.background !== "") imgTool.background = body.background;
    return {
      model: responsesModel,
      instructions: "",
      input: [{ type: "message", role: "user", content: buildContent(body.prompt, refs, detail) }],
      tools: [imgTool],
      tool_choice: toolModel ? { type: "image_generation" } : "auto",
      parallel_tool_calls: false,
      prompt_cache_key: randomUUID(),
      stream: true,
      store: false,
      reasoning: null,
    };
  },
  // Custom: codex parses SSE → either pipe to client or collect b64
  async parseResponse(response, { log, streamToClient, onRequestSuccess, onUsage, requestBody }) {
    if (requestBody?.prompt && !requestBody?.input) {
      let payload;
      try {
        payload = await response.json();
      } catch {
        throw new Error("Codex Images API returned invalid JSON.");
      }
      const data = Array.isArray(payload?.data) ? payload.data : [];
      if (!data.some((item) => item?.b64_json || item?.url)) {
        const error = payload?.error || {};
        const err = new Error(error.message || "Codex Images API returned no image.");
        for (const key of ["code", "type", "param"]) {
          if (typeof error[key] === "string") err[key] = error[key];
        }
        throw err;
      }
      const result = { created: payload.created || nowSec(), data };
      const usage = normalizeResponsesUsage(payload.usage);
      if (streamToClient) {
        if (usage && onUsage) await onUsage(usage);
        if (onRequestSuccess) await onRequestSuccess();
        return { sseResponse: nativeImageSseResponse(result) };
      }
      if (usage && onUsage) await onUsage(usage);
      return result;
    }

    if (streamToClient) {
      return { sseResponse: buildSseResponse(response, log, onRequestSuccess, onUsage) };
    }
    const { imageB64: b64, usage, error: upstreamError } = await parseStream(response, log);
    if (!b64) {
      throw new Error(upstreamError || "Codex completed without an image. No upstream image result was provided.");
    }
    if (usage && onUsage) await onUsage(usage);
    return { created: nowSec(), data: [{ b64_json: b64 }] };
  },
  normalize: (responseBody) => responseBody,
};

