"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import Card from "@/shared/components/Card";
import PricingModal from "@/shared/components/PricingModal";

export default function PricingSettingsPage() {
  const router = useRouter();
  const [showModal, setShowModal] = useState(false);
  const [currentPricing, setCurrentPricing] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadPricing();
  }, []);

  const loadPricing = async () => {
    setLoading(true);
    try {
      const response = await fetch("/api/pricing");
      if (response.ok) {
        const data = await response.json();
        setCurrentPricing(data);
      }
    } catch (error) {
      console.error("Failed to load pricing:", error);
    } finally {
      setLoading(false);
    }
  };

  const handlePricingUpdated = () => {
    loadPricing();
  };

  // Count total models with pricing
  const getModelCount = () => {
    if (!currentPricing) return 0;
    let count = 0;
    for (const provider in currentPricing) {
      count += Object.keys(currentPricing[provider]).length;
    }
    return count;
  };

  // Get providers list
  const getProviders = () => {
    if (!currentPricing) return [];
    return Object.keys(currentPricing).sort();
  };

  return (
    <div className="max-w-6xl mx-auto p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Pricing Settings</h1>
          <p className="text-text-muted mt-1">
            Configure pricing rates for cost tracking and calculations
          </p>
        </div>
        <button
          onClick={() => setShowModal(true)}
          className="px-4 py-2 bg-primary text-white rounded hover:bg-primary/90 transition-colors"
        >
          Edit Pricing
        </button>
      </div>

      {/* Quick Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card className="p-4">
          <div className="text-text-muted text-sm uppercase font-semibold">
            Total Models
          </div>
          <div className="text-2xl font-bold mt-1">
            {loading ? "..." : getModelCount()}
          </div>
        </Card>
        <Card className="p-4">
          <div className="text-text-muted text-sm uppercase font-semibold">
            Providers
          </div>
          <div className="text-2xl font-bold mt-1">
            {loading ? "..." : getProviders().length}
          </div>
        </Card>
        <Card className="p-4">
          <div className="text-text-muted text-sm uppercase font-semibold">
            Status
          </div>
          <div className="text-2xl font-bold mt-1 text-success">
            {loading ? "..." : "Active"}
          </div>
        </Card>
      </div>

      {/* Info Section */}
      <Card className="p-6">
        <h2 className="text-xl font-semibold mb-4">How Pricing Works</h2>
        <div className="space-y-3 text-sm text-text-muted">
          <p>
            <strong>Cost Calculation:</strong> Costs are calculated based on token usage and pricing rates.
            Each request&apos;s cost is determined by: (input_tokens × input_rate) + (output_tokens × output_rate) + (cached_tokens × cached_rate)
          </p>
          <p>
            <strong>Pricing Format:</strong> All rates are in <strong>dollars per million tokens</strong> ($/1M tokens).
            Example: An input rate of 2.50 means $2.50 per 1,000,000 input tokens.
          </p>
          <p>
            <strong>Token Types:</strong>
          </p>
          <ul className="list-disc list-inside ml-4 space-y-1">
            <li><strong>Input:</strong> Standard prompt tokens</li>
            <li><strong>Output:</strong> Completion/response tokens</li>
            <li><strong>Cached:</strong> Cached input tokens (typically 50% of input rate)</li>
            <li><strong>Reasoning:</strong> Special reasoning/thinking tokens (fallback to output rate)</li>
            <li><strong>Cache Creation:</strong> Tokens used to create cache entries (fallback to input rate)</li>
          </ul>
          <p>
            <strong>Custom Pricing:</strong> You can override default pricing for specific models.
            Reset to defaults anytime to restore standard rates.
          </p>
        </div>
      </Card>

      {/* Current Pricing Preview */}
      <Card className="p-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl font-semibold">Current Pricing Overview</h2>
          <button
            onClick={() => setShowModal(true)}
            className="text-primary hover:underline text-sm"
          >
            View Full Details
          </button>
        </div>

        {loading ? (
          <div className="text-center py-4 text-text-muted">Loading pricing data...</div>
        ) : currentPricing ? (
          <div className="space-y-3">
            {Object.keys(currentPricing).slice(0, 5).map(provider => (
              <div key={provider} className="text-sm">
                <span className="font-semibold">{provider.toUpperCase()}:</span>{" "}
                <span className="text-text-muted">
                  {Object.keys(currentPricing[provider]).length} models
                </span>
              </div>
            ))}
            {Object.keys(currentPricing).length > 5 && (
              <div className="text-sm text-text-muted">
                + {Object.keys(currentPricing).length - 5} more providers
              </div>
            )}
          </div>
        ) : (
          <div className="text-text-muted">No pricing data available</div>
        )}
      </Card>

      {/* Pricing Modal */}
      {showModal && (
        <PricingModal
          isOpen={showModal}
          onClose={() => setShowModal(false)}
          onSave={handlePricingUpdated}
        />
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { Card, Button, Input } from "@/shared/components";

export default function LoginPage() {
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [resetHint, setResetHint] = useState("");
  const [retryAfter, setRetryAfter] = useState(0);
  const [loading, setLoading] = useState(false);
  const [hasPassword, setHasPassword] = useState(null);
  const [authMode, setAuthMode] = useState("password");
  const [ssoType, setSsoType] = useState("oidc");
  const [oidcConfigured, setOidcConfigured] = useState(false);
  const [oidcLoginLabel, setOidcLoginLabel] = useState("Sign in with OIDC");
  const [samlConfigured, setSamlConfigured] = useState(false);
  const [samlLoginLabel, setSamlLoginLabel] = useState("Sign in with SAML SSO");
  const [mustChange, setMustChange] = useState(false);
  const [newPassword, setNewPassword] = useState("");

  // Countdown for rate-limit
  useEffect(() => {
    if (retryAfter <= 0) return;
    const id = setInterval(() => setRetryAfter((s) => (s > 0 ? s - 1 : 0)), 1000);
    return () => clearInterval(id);
  }, [retryAfter]);

  useEffect(() => {
    async function checkAuth() {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 5000);
      const baseUrl = typeof window !== "undefined" ? window.location.origin : "";

      try {
        const res = await fetch(`${baseUrl}/api/auth/status`, {
          signal: controller.signal,
        });
        clearTimeout(timeoutId);

        if (res.ok) {
          const data = await res.json();
          if (data.authenticated === true || data.requireLogin === false) {
            window.location.assign("/dashboard");
            return;
          }
          setHasPassword(!!data.hasPassword);
          setAuthMode(data.authMode || "password");
          setSsoType(data.ssoType || "oidc");
          setOidcConfigured(data.oidcConfigured === true);
          setOidcLoginLabel(data.oidcLoginLabel || "Sign in with OIDC");
          setSamlConfigured(data.samlConfigured === true);
          setSamlLoginLabel(data.samlLoginLabel || "Sign in with SAML SSO");
        } else {
          // Safe fallback on non-OK response to avoid infinite loading state.
          setHasPassword(true);
        }
      } catch (err) {
        clearTimeout(timeoutId);
        setHasPassword(true);
      }
    }
    checkAuth();
  }, []);

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError("");
    setResetHint("");

    try {
      const res = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ password }),
      });

      if (res.ok) {
        const data = await res.json();
        if (data.mustChangePassword) {
          setMustChange(true);
          return;
        }
        window.location.assign("/dashboard");
      } else {
        const data = await res.json();
        setError(data.error || "Invalid password");
        if (data.resetHint) setResetHint(data.resetHint);
        if (data.retryAfter) setRetryAfter(Number(data.retryAfter));
      }
    } catch (err) {
      setError("An error occurred. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  // Force a new password before entering the dashboard (default + remote).
  const handleSetNewPassword = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError("");
    try {
      const res = await fetch("/api/settings", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ currentPassword: password, newPassword }),
      });
      if (res.ok) {
        window.location.assign("/dashboard");
      } else {
        const data = await res.json();
        setError(data.error || "Failed to set password");
      }
    } catch (err) {
      setError("An error occurred. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleOidcLogin = () => {
    window.location.href = "/api/auth/oidc/start";
  };

  const handleSamlLogin = () => {
    window.location.href = "/api/auth/saml/start";
  };

  const isSsoEnabled = ["sso", "oidc", "saml", "both"].includes(authMode);
  const activeSsoType = ssoType || (authMode === "saml" ? "saml" : "oidc");

  const samlAvailable = isSsoEnabled && activeSsoType === "saml" && samlConfigured;
  const oidcAvailable = isSsoEnabled && activeSsoType === "oidc" && oidcConfigured;
  const ssoAvailable = samlAvailable || oidcAvailable;

  const passwordAvailable = authMode === "password" || authMode === "both" || !ssoAvailable;

  // Show loading state while checking password
  if (hasPassword === null) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-bg p-4">
        <div className="text-center">
          <div className="inline-block animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
          <p className="text-text-muted mt-4">Loading...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-bg p-4 relative overflow-hidden">
      {/* Faint grid background */}
      <div className="landing-grid absolute inset-0 pointer-events-none" aria-hidden="true" />
      <div className="relative z-10 w-full max-w-md">
        <div className="text-center mb-8">
          <h1 className="text-3xl font-bold text-primary mb-2">9Router</h1>
          <p className="text-text-muted">
            {samlAvailable
              ? "Sign in with SAML 2.0 Single Sign-On"
              : oidcAvailable
              ? "Sign in with your OIDC provider to access the dashboard"
              : "Enter your password to access the dashboard"}
          </p>
        </div>

        <Card>
          {mustChange ? (
            <form onSubmit={handleSetNewPassword} className="flex flex-col gap-4">
              <p className="text-sm text-amber-600 dark:text-amber-400 text-center">
                Set a new password before accessing the dashboard remotely.
              </p>
              <div className="flex flex-col gap-2">
                <label className="text-sm font-medium">New password</label>
                <Input
                  type="password"
                  placeholder="Enter new password"
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                  required
                  autoFocus
                />
                {error && <p className="text-xs text-red-500">{error}</p>}
              </div>
              <Button type="submit" variant="primary" className="w-full" loading={loading} disabled={!newPassword}>
                Set password
              </Button>
            </form>
          ) : (
          <div className="flex flex-col gap-4">
            {samlAvailable && (
              <Button type="button" variant="primary" className="w-full" onClick={handleSamlLogin}>
                {samlLoginLabel}
              </Button>
            )}

            {oidcAvailable && (
              <Button type="button" variant="primary" className="w-full" onClick={handleOidcLogin}>
                {oidcLoginLabel}
              </Button>
            )}

            {ssoAvailable && passwordAvailable && <div className="h-px bg-border/60" />}

            {passwordAvailable ? (
              <form onSubmit={handleLogin} className="flex flex-col gap-4">
                {isSsoEnabled && !ssoAvailable && (
                  <p className="text-xs text-amber-600 dark:text-amber-400 text-center">
                    {activeSsoType === "saml" ? "SAML SSO" : "OIDC"} login is enabled, but configuration is incomplete. Password login is still available for recovery.
                  </p>
                )}

                {authMode === "both" && ssoAvailable && (
                  <p className="text-xs text-text-muted text-center">
                    Password and {activeSsoType === "saml" ? "SAML SSO" : "OIDC"} login are both enabled.
                  </p>
                )}

                <div className="flex flex-col gap-2">
                  <label className="text-sm font-medium">Password</label>
                  <Input
                    type="password"
                    placeholder="Enter password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                    autoFocus={!oidcAvailable}
                  />
                  {error && <p className="text-xs text-red-500">{error}</p>}
                  {retryAfter > 0 && (
                    <p className="text-xs text-amber-600 dark:text-amber-400">
                      Locked. Retry in <span className="font-mono">{retryAfter}s</span>.
                    </p>
                  )}
                  {resetHint && (
                    <p className="text-xs text-text-muted">
                      Forgot password? Open <code className="bg-sidebar px-1 rounded">9router</code> CLI on the host → <b>Settings</b> → <b>Reset Password to Default</b>.
                    </p>
                  )}
                </div>

                <Button
                  type="submit"
                  variant="primary"
                  className="w-full"
                  loading={loading}
                  disabled={retryAfter > 0}
                >
                  {retryAfter > 0 ? `Wait ${retryAfter}s` : "Login"}
                </Button>

                <p className="text-xs text-center text-text-muted mt-2">
                  Default password is <code className="bg-sidebar px-1 rounded">123456</code>
                </p>
                {hasPassword === false && (
                  <p className="text-xs text-center text-amber-600 dark:text-amber-400">
                    Security risk: no password set. You will be asked to set one when logging in remotely.
                  </p>
                )}
              </form>
            ) : (
              error && <p className="text-xs text-red-500">{error}</p>
            )}
          </div>
          )}
        </Card>
        <p className="mt-5 text-center text-xs text-text-muted">
          Have an API key?{" "}
          <Link href="/key-usage" className="font-semibold text-primary hover:underline">
            View your usage
          </Link>
        </p>
      </div>
    </div>
  );
}

// Initial schema bootstrap. For fresh DB this creates all tables/indexes.
// For existing DB at version 0 (legacy unstamped), it's idempotent (IF NOT EXISTS).
import { TABLES, buildCreateTableSql } from "../schema.js";

export default {
  version: 1,
  name: "initial",
  up(db) {
    for (const [name, def] of Object.entries(TABLES)) {
      db.exec(buildCreateTableSql(name, def));
      // A legacy, unstamped database may already have an older version of a
      // table. Some current indexes reference columns that are intentionally
      // added by later migrations/additive sync, so defer those indexes until
      // their columns exist instead of aborting the whole migration chain.
      for (const idx of def.indexes || []) {
        try { db.exec(idx); } catch { /* additive sync retries after columns */ }
      }
    }
  },
};

// Project Memory schema is declared in schema.js so fresh databases and the
// additive synchronizer share one source of truth. This migration exists to
// backfill ownership for pre-existing API keys and seed the global feature row.
import { TABLES, buildCreateTableSql } from "../schema.js";
import { isProtectedApiKeyRow, protectApiKey } from "@/lib/apiKeyStorage.js";

const PROJECT_TABLES = [
  "projectSystemSettings", "projectPermissions", "projects", "projectMembers",
  "projectApiKeys", "projectSettings", "projectSessions", "memoryEvents",
  "extractionJobs", "memoryItems", "memoryItemHistory", "memoryEntities",
  "memoryRelations", "projectFiles", "projectSymbols", "projectFileDependencies",
  "contextSnapshots", "memoryUsage",
];

export default {
  version: 2,
  name: "project-memory-engine",
  up(db) {
    const apiKeyColumns = new Set(db.all("PRAGMA table_info(apiKeys)").map((row) => row.name));
    if (!apiKeyColumns.has("ownerId")) db.exec("ALTER TABLE apiKeys ADD COLUMN ownerId TEXT DEFAULT 'local-admin'");
    if (!apiKeyColumns.has("projectAccess")) db.exec("ALTER TABLE apiKeys ADD COLUMN projectAccess INTEGER NOT NULL DEFAULT 1");
    if (!apiKeyColumns.has("keyHash")) db.exec("ALTER TABLE apiKeys ADD COLUMN keyHash TEXT");
    if (!apiKeyColumns.has("keyEncrypted")) db.exec("ALTER TABLE apiKeys ADD COLUMN keyEncrypted TEXT");
    for (const row of db.all("SELECT id, key, keyHash, keyEncrypted, machineId FROM apiKeys")) {
      if (isProtectedApiKeyRow(row)) continue;
      const protectedKey = protectApiKey(row.key, row.machineId);
      db.run("UPDATE apiKeys SET key=?, keyHash=?, keyEncrypted=? WHERE id=?", [protectedKey.storageKey, protectedKey.keyHash, protectedKey.keyEncrypted, row.id]);
    }
    db.exec("UPDATE apiKeys SET ownerId = 'local-admin' WHERE ownerId IS NULL OR ownerId = ''");

    for (const name of PROJECT_TABLES) {
      const def = TABLES[name];
      db.exec(buildCreateTableSql(name, def));
      for (const index of def.indexes || []) {
        try { db.exec(index); } catch { /* later migrations may add referenced columns */ }
      }
    }
    // FTS5 is optional at the driver level (not every sql.js build includes
    // it). The relational search path remains fully functional when this DDL
    // is unavailable.
    try {
      db.exec(`CREATE VIRTUAL TABLE IF NOT EXISTS projectSearch USING fts5(
        projectId UNINDEXED, kind UNINDEXED, refId UNINDEXED, title, body,
        tokenize='unicode61 remove_diacritics 2'
      )`);
    } catch { /* relational fallback */ }
    const now = new Date().toISOString();
    db.run(
      `INSERT OR IGNORE INTO projectSystemSettings(
        id, enabled, defaultUserAccess, extractionEnabled, retrievalEnabled,
        fileIndexingEnabled, maxProjectsPerUser, maxFilesPerProject,
        maxProjectBytes, maxFileBytes, updatedAt
      ) VALUES(1, 1, 1, 1, 1, 1, 50, 5000, 268435456, 10485760, ?)`,
      [now],
    );
  },
  // The migration runner intentionally never calls down automatically. Keeping
  // this explicit makes controlled development rollback auditable.
  down(db) {
    try { db.exec("DROP TABLE IF EXISTS projectSearch"); } catch { /* optional */ }
    for (const name of [...PROJECT_TABLES].reverse()) db.exec(`DROP TABLE IF EXISTS ${name}`);
  },
};

function normalizedName(value) {
  const name = String(value || "").replace(/\s+/g, " ").trim();
  return (name || "Project").slice(0, 120);
}

function suffixedName(name, number) {
  const suffix = ` (${number})`;
  return `${name.slice(0, 120 - suffix.length).trimEnd()}${suffix}`;
}

export default {
  version: 3,
  name: "project-quota-and-unique-names",
  up(db) {
    const keyColumns = new Set(db.all("PRAGMA table_info(apiKeys)").map((row) => row.name));
    if (!keyColumns.has("maxProjects")) db.exec("ALTER TABLE apiKeys ADD COLUMN maxProjects INTEGER");

    const columns = new Set(db.all("PRAGMA table_info(projects)").map((row) => row.name));
    if (!columns.has("nameKey")) db.exec("ALTER TABLE projects ADD COLUMN nameKey TEXT");
    if (!columns.has("createdByApiKeyId")) {
      db.exec("ALTER TABLE projects ADD COLUMN createdByApiKeyId TEXT REFERENCES apiKeys(id) ON DELETE SET NULL");
    }

    db.exec(`CREATE TABLE IF NOT EXISTS projectApiKeyMembers (
      projectId TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
      apiKeyId TEXT NOT NULL REFERENCES apiKeys(id) ON DELETE CASCADE,
      addedBy TEXT NOT NULL,
      addedAt TEXT NOT NULL,
      PRIMARY KEY (projectId, apiKeyId)
    )`);
    db.exec("CREATE INDEX IF NOT EXISTS idx_pakm_key ON projectApiKeyMembers(apiKeyId)");
    db.exec("CREATE INDEX IF NOT EXISTS idx_pakm_project ON projectApiKeyMembers(projectId)");
    db.exec("CREATE INDEX IF NOT EXISTS idx_projects_created_by_key ON projects(createdByApiKeyId)");
    db.exec(`INSERT OR IGNORE INTO projectApiKeyMembers(projectId, apiKeyId, addedBy, addedAt)
      SELECT projectId, apiKeyId, assignedBy, assignedAt FROM projectApiKeys`);

    const rows = db.all("SELECT id, name, createdAt FROM projects ORDER BY createdAt ASC, id ASC")
      .map((row) => ({ ...row, normalized: normalizedName(row.name) }));
    const reserved = new Set(rows.map((row) => row.normalized.toLowerCase()));
    const used = new Set();
    const suffixes = new Map();
    for (const row of rows) {
      let name = row.normalized;
      let key = name.toLowerCase();
      if (used.has(key)) {
        let number = suffixes.get(key) || 2;
        do {
          name = suffixedName(row.normalized, number++);
          key = name.toLowerCase();
        } while (used.has(key) || reserved.has(key));
        suffixes.set(row.normalized.toLowerCase(), number);
      }
      used.add(key);
      db.run("UPDATE projects SET name=?, nameKey=? WHERE id=?", [name, key, row.id]);
    }

    db.exec("CREATE UNIQUE INDEX IF NOT EXISTS idx_projects_name_key_unique ON projects(nameKey) WHERE nameKey IS NOT NULL");
    db.exec(`CREATE TRIGGER IF NOT EXISTS trg_projects_quota_insert
      BEFORE INSERT ON projects
      WHEN NEW.status <> 'archived' AND
        (SELECT COUNT(*) FROM projects WHERE ownerId=NEW.ownerId AND status <> 'archived') >=
        COALESCE((SELECT maxProjectsPerUser FROM projectSystemSettings WHERE id=1), 50)
      BEGIN SELECT RAISE(ABORT, 'PROJECT_LIMIT'); END`);
    db.exec(`CREATE TRIGGER IF NOT EXISTS trg_projects_key_quota_insert
      BEFORE INSERT ON projects
      WHEN NEW.status <> 'archived' AND NEW.createdByApiKeyId IS NOT NULL AND
        (SELECT maxProjects FROM apiKeys WHERE id=NEW.createdByApiKeyId) IS NOT NULL AND
        (SELECT COUNT(*) FROM projects WHERE createdByApiKeyId=NEW.createdByApiKeyId AND status <> 'archived') >=
        (SELECT maxProjects FROM apiKeys WHERE id=NEW.createdByApiKeyId)
      BEGIN SELECT RAISE(ABORT, 'PROJECT_LIMIT'); END`);
    db.exec(`CREATE TRIGGER IF NOT EXISTS trg_projects_quota_update
      BEFORE UPDATE OF ownerId, status ON projects
      WHEN NEW.status <> 'archived' AND (OLD.status = 'archived' OR NEW.ownerId <> OLD.ownerId) AND
        (SELECT COUNT(*) FROM projects WHERE ownerId=NEW.ownerId AND status <> 'archived' AND id <> OLD.id) >=
        COALESCE((SELECT maxProjectsPerUser FROM projectSystemSettings WHERE id=1), 50)
      BEGIN SELECT RAISE(ABORT, 'PROJECT_LIMIT'); END`);
  },
};

import { execFile } from "child_process";
import { promisify } from "util";
import { access, constants, readFile } from "fs/promises";
import { homedir } from "os";
import { join } from "path";
import { randomUUID } from "crypto";

const execFileAsync = promisify(execFile);

export const ZED_DEFAULT_CREDENTIALS_URL = "https://zed.dev";
export const ZED_KEYRING_LABEL = "zed-github-account";

/**
 * Resolve the credential URL Zed uses as the keyring/keychain key.
 * Defaults to https://zed.dev; honors settings.json credentials_url → server_url.
 */
export async function resolveZedCredentialsUrl() {
  const settingsPaths = getZedSettingsPaths();
  for (const settingsPath of settingsPaths) {
    try {
      await access(settingsPath, constants.R_OK);
      const raw = await readFile(settingsPath, "utf8");
      const settings = JSON.parse(raw);
      const url =
        (typeof settings?.credentials_url === "string" && settings.credentials_url) ||
        (typeof settings?.server_url === "string" && settings.server_url) ||
        null;
      if (url) return url.replace(/\/+$/, "");
    } catch {
      // try next path
    }
  }
  return ZED_DEFAULT_CREDENTIALS_URL;
}

function getZedSettingsPaths() {
  const home = homedir();
  if (process.platform === "darwin") {
    return [join(home, "Library/Application Support/Zed/settings.json")];
  }
  if (process.platform === "win32") {
    const local = process.env.LOCALAPPDATA || join(home, "AppData", "Local");
    return [join(local, "Zed", "settings.json")];
  }
  const xdg = process.env.XDG_CONFIG_HOME || join(home, ".config");
  return [join(xdg, "zed", "settings.json")];
}

/** Candidate paths for Zed's global kv_store (holds system_id). */
export function getZedGlobalDbPaths() {
  const home = homedir();
  const channels = ["0-global", "0-stable", "0-preview"];
  if (process.platform === "darwin") {
    const base = join(home, "Library/Application Support/Zed/db");
    return channels.map((c) => join(base, c, "db.sqlite"));
  }
  if (process.platform === "win32") {
    const local = process.env.LOCALAPPDATA || join(home, "AppData", "Local");
    const base = join(local, "Zed", "db");
    return channels.map((c) => join(base, c, "db.sqlite"));
  }
  const xdg = process.env.XDG_DATA_HOME || join(home, ".local", "share");
  const base = join(xdg, "zed", "db");
  return channels.map((c) => join(base, c, "db.sqlite"));
}

/**
 * Read system_id from Zed's local kv_store (same id the IDE sends to cloud.zed.dev).
 */
export async function readZedSystemId() {
  for (const dbPath of getZedGlobalDbPaths()) {
    try {
      await access(dbPath, constants.R_OK);
    } catch {
      continue;
    }
    const value = await queryKvStore(dbPath, "system_id");
    if (value) return String(value).trim();
  }
  return null;
}

async function queryKvStore(dbPath, key) {
  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const Database = require("better-sqlite3");
    const db = new Database(dbPath, { readonly: true, fileMustExist: true });
    try {
      const row = db.prepare("SELECT value FROM kv_store WHERE key = ? LIMIT 1").get(key);
      return row?.value || null;
    } finally {
      db.close();
    }
  } catch {
    // Fall back to sqlite3 CLI when native bindings are unavailable.
  }

  try {
    const { stdout } = await execFileAsync(
      "sqlite3",
      [dbPath, `SELECT value FROM kv_store WHERE key='${key.replace(/'/g, "''")}' LIMIT 1;`],
      { timeout: 5000, windowsHide: true },
    );
    const value = String(stdout || "").trim();
    return value || null;
  } catch {
    return null;
  }
}

/**
 * Read Zed IDE session credentials from the OS secret store.
 * @returns {Promise<{ found: boolean, userId?: string, accessToken?: string, systemId?: string, credentialsUrl?: string, error?: string }>}
 */
export async function readZedIdeCredentials() {
  const credentialsUrl = await resolveZedCredentialsUrl();
  let pair = null;

  if (process.platform === "linux") {
    pair = await readLinuxCredentials(credentialsUrl);
  } else if (process.platform === "darwin") {
    pair = await readMacCredentials(credentialsUrl);
  } else if (process.platform === "win32") {
    pair = await readWindowsCredentials(credentialsUrl);
  } else {
    return {
      found: false,
      error: `Zed auto-import is not supported on platform ${process.platform}`,
      credentialsUrl,
    };
  }

  if (!pair?.userId || !pair?.accessToken) {
    return {
      found: false,
      error:
        pair?.error ||
        "Zed IDE session not found in the system keyring. Sign in to Zed, then retry.",
      credentialsUrl,
    };
  }

  const systemId = (await readZedSystemId()) || randomUUID();
  return {
    found: true,
    userId: String(pair.userId),
    accessToken: String(pair.accessToken),
    systemId,
    credentialsUrl,
  };
}

async function readLinuxCredentials(credentialsUrl) {
  // Zed (oo7): attributes url + username, label "zed-github-account".
  // Note: secret-tool prints attribute.* lines on stderr and label/secret on stdout.
  try {
    const { stdout, stderr } = await execFileAsync(
      "secret-tool",
      ["search", "--all", "url", credentialsUrl],
      { timeout: 8000, windowsHide: true },
    );
    const items = parseSecretToolSearch(`${stderr || ""}\n${stdout || ""}`);
    const match =
      items.find((item) => item.label === ZED_KEYRING_LABEL && item.username && item.secret) ||
      items.find((item) => item.username && item.secret) ||
      null;
    if (match?.username && match?.secret) {
      return { userId: match.username, accessToken: match.secret };
    }
  } catch (err) {
    if (err?.code === "ENOENT") {
      return { error: "secret-tool not found (install libsecret / secret-tools)" };
    }
    // Some secret-tool versions exit non-zero but still print useful output.
    const merged = `${err?.stderr || ""}\n${err?.stdout || ""}`;
    if (merged.includes("secret =")) {
      const items = parseSecretToolSearch(merged);
      const match = items.find((item) => item.username && item.secret);
      if (match) return { userId: match.username, accessToken: match.secret };
    }
  }

  try {
    const lookup = await execFileAsync(
      "secret-tool",
      ["lookup", "url", credentialsUrl],
      { timeout: 8000, windowsHide: true },
    );
    const accessToken = String(lookup.stdout || "").trim();
    if (!accessToken) return { error: "Empty Zed keyring secret" };

    const search = await execFileAsync(
      "secret-tool",
      ["search", "--all", "url", credentialsUrl],
      { timeout: 8000, windowsHide: true },
    );
    const items = parseSecretToolSearch(`${search.stderr || ""}\n${search.stdout || ""}`);
    const userId = items.find((i) => i.username)?.username;
    if (!userId) return { error: "Zed keyring entry missing username (user id)" };
    return { userId, accessToken };
  } catch (err) {
    if (err?.code === "ENOENT") {
      return { error: "secret-tool not found (install libsecret / secret-tools)" };
    }
    return { error: err?.stderr || err?.message || "Failed to read Linux keyring" };
  }
}

function parseSecretToolSearch(stdout) {
  // Attributes are often on stderr; callers should concatenate stderr+stdout.
  // Format:
  //   attribute.url = https://zed.dev
  //   attribute.username = 123
  //   [/60]
  //   label = zed-github-account
  //   secret = {...}
  const text = String(stdout || "");
  const username = text.match(/attribute\.username\s*=\s*(\S+)/)?.[1] || null;
  const label = text.match(/^\s*label\s*=\s*(.+)$/m)?.[1]?.trim() || null;
  const secretLine = text.match(/^\s*secret\s*=\s*(.*)$/m)?.[1];
  const secret = secretLine != null ? secretLine.trim() : null;
  if (!username && !secret && !label) return [];
  return [{ label, username, secret }];
}

async function readMacCredentials(credentialsUrl) {
  // Zed stores an internet password with kSecAttrServer = full credentials URL.
  const servers = unique([credentialsUrl, stripUrlScheme(credentialsUrl), "zed.dev"]);
  let lastError = null;

  for (const server of servers) {
    try {
      // -g prints password to stderr as "password: \"...\""
      const { stdout, stderr } = await execFileAsync(
        "security",
        ["find-internet-password", "-s", server, "-g"],
        { timeout: 8000, windowsHide: true },
      );
      const combined = `${stdout || ""}\n${stderr || ""}`;
      const password = parseSecurityPassword(combined);
      const account =
        combined.match(/"acct"<blob>="([^"]*)"/)?.[1] ||
        combined.match(/"acct"<blob>=0x[0-9A-Fa-f]+\s+"([^"]*)"/)?.[1] ||
        null;
      if (password && account) {
        return { userId: account, accessToken: password };
      }
      if (password && !account) {
        lastError = "Found Zed keychain password but missing account (user id)";
      }
    } catch (err) {
      lastError = err?.stderr || err?.message || lastError;
    }
  }
  return { error: lastError || "Zed credentials not found in macOS Keychain" };
}

function parseSecurityPassword(text) {
  const m = String(text).match(/password:\s*"(.*)"\s*$/m);
  if (m) return unescapeSecurityPassword(m[1]);
  // Empty password prints as "password: "
  if (/password:\s*$/m.test(text)) return "";
  return null;
}

function unescapeSecurityPassword(value) {
  // security escapes \ and " in the quoted password dump
  return value.replace(/\\(.)/g, "$1");
}

async function readWindowsCredentials(credentialsUrl) {
  // Zed target name: zed:url=https://zed.dev
  const target = `zed:url=${credentialsUrl}`;
  const script = `
$ErrorActionPreference = 'Stop'
Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
using System.Text;
public class ZedCred {
  [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
  public struct CREDENTIAL {
    public uint Flags; public uint Type; public string TargetName; public string Comment;
    public System.Runtime.InteropServices.ComTypes.FILETIME LastWritten;
    public uint CredentialBlobSize; public IntPtr CredentialBlob; public uint Persist;
    public uint AttributeCount; public IntPtr Attributes; public string TargetAlias; public string UserName;
  }
  [DllImport("advapi32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
  public static extern bool CredRead(string target, uint type, uint reservedFlag, out IntPtr credentialPtr);
  [DllImport("advapi32.dll", SetLastError = true)]
  public static extern void CredFree(IntPtr buffer);
  public static string Read(string target) {
    IntPtr p;
    if (!CredRead(target, 1, 0, out p)) return null;
    try {
      var c = (CREDENTIAL)Marshal.PtrToStructure(p, typeof(CREDENTIAL));
      string secret = "";
      if (c.CredentialBlob != IntPtr.Zero && c.CredentialBlobSize > 0) {
        byte[] bytes = new byte[c.CredentialBlobSize];
        Marshal.Copy(c.CredentialBlob, bytes, 0, (int)c.CredentialBlobSize);
        secret = Encoding.UTF8.GetString(bytes);
      }
      return (c.UserName ?? "") + "\\n" + secret;
    } finally { CredFree(p); }
  }
}
"@
$r = [ZedCred]::Read(${JSON.stringify(target)})
if ($null -eq $r) { exit 2 }
Write-Output $r
`.trim();

  try {
    const { stdout } = await execFileAsync(
      "powershell.exe",
      ["-NoProfile", "-NonInteractive", "-Command", script],
      { timeout: 15000, windowsHide: true, maxBuffer: 2 * 1024 * 1024 },
    );
    const text = String(stdout || "").replace(/^\uFEFF/, "");
    const nl = text.indexOf("\n");
    if (nl < 0) return { error: "Malformed Windows credential payload" };
    const userId = text.slice(0, nl).trim();
    const accessToken = text.slice(nl + 1).replace(/\r?\n$/, "");
    if (!userId || !accessToken) {
      return { error: "Windows Credential Manager entry missing username or secret" };
    }
    return { userId, accessToken };
  } catch (err) {
    if (err?.code === 2 || err?.status === 2) {
      return { error: "Zed credentials not found in Windows Credential Manager" };
    }
    return { error: err?.stderr || err?.message || "Failed to read Windows credentials" };
  }
}

function stripUrlScheme(url) {
  return String(url || "").replace(/^https?:\/\//i, "").replace(/\/+$/, "");
}

function unique(arr) {
  return [...new Set(arr.filter(Boolean))];
}

